          responseOptions: ["Our agenda today covers three core areas: the checkout redesign, API performance benchmarks, and our rollout timeline.", "Today we will walk through the sprint deliverables, user feedback, and our budget allocation."],
          bestResponseIndex: 0,
          speechTip: "Structure the agenda into 2 or 3 distinct thematic pillars.",
        ),
        SpokenDialogueExchange(
          stepIndex: 3,
          avatarPrompt: "Client asks: Before we begin, will there be dedicated time for questions at the end?",
          avatarPromptMl: "സംശയങ്ങൾ ചോദിക്കാൻ അവസാനം സമയം മാറ്റി വെച്ചിട്ടുണ്ടോ എന്ന് ചോദിച്ചാൽ എന്ത് മറുപടി നൽകും?",
          responseOptions: ["Yes, we have reserved fifteen minutes at the end for an open Q&A discussion.", "Absolutely. Feel free to raise questions as we go, or during our dedicated Q&A session at the end."],
