    69: DaySpokenSimulatorPlan(
      day: 69,
      topicTitle: "First Conditional: Real Future Possibilities",
      topicTitleMl: "ഭാവിയിലെ യാഥാർത്ഥ്യങ്ങൾ (If + Present, Will + V1)",
