    71: DaySpokenSimulatorPlan(
      day: 71,
      topicTitle: "Modals of Probability: May, Might, Could",
      topicTitleMl: "സാധ്യതകൾ പ്രകടിപ്പിക്കൽ (May, Might, Could)",
      scenarioContext: "ഒരു കാര്യം നടക്കാൻ 50% ഓ അതിൽ താഴെയോ സാധ്യതയുള്ളപ്പോൾ may, might, could എന്നിവ ഉപയോഗിക്കുന്നു. \'May\' കുറച്ചുകൂടി ഔദ്യോഗികവും ഉയർന്ന സാധ്യതയുള്ളതുമാണ് (50%), \'Might\' കുറഞ്ഞ സാധ്യതയെയും (30-40%), \'Could\' സൈദ്ധാന്തിക സാധ്യതയെയും സൂചിപ്പിക്കുന്നു.",
      exchanges: const [
        SpokenDialogueExchange(
          stepIndex: 1,
