          avatarPromptMl: "നമ്മുടെ ഉൽപ്പന്ന ലോഞ്ച് ആസൂത്രണം ചെയ്തതുപോലെ നവംബർ ഒന്നിന് നടക്കുമെന്ന് നിങ്ങൾ കരുതുന്നുണ്ടോ?",
