      scenarioContext: "പ്രവൃത്തി ചെയ്ത ആളെക്കാൾ പ്രവൃത്തിക്ക് മുൻഗണന നൽകുന്ന ഔദ്യോഗിക റിപ്പോർട്ടുകളിലും വാർത്തകളിലും Passive Voice ഉപയോഗിക്കുന്നു. ഉദാഹരണത്തിന്: \'The report has been submitted\' (റിപ്പോർട്ട് സമർപ്പിക്കപ്പെട്ടു).",
      exchanges: const [
        SpokenDialogueExchange(
          stepIndex: 1,
          avatarPrompt: "Has the new data protection policy been communicated to our regional branches?",
          avatarPromptMl: "പുതിയ ഡാറ്റാ സംരക്ഷണ നയം ഞങ്ങളുടെ റീജിയണൽ ബ്രാഞ്ചുകളെ അറിയിച്ചിട്ടുണ്ടോ?",
