          avatarPromptMl: "തീർച്ചയായും നായർ! ഞാൻ അദ്ദേഹത്തിന്റെ ഡെസ്കിൽ ഒന്ന് നോക്കട്ടെ. ദയവായി അല്പം കാത്തിരിക്കാമോ?",
          responseOptions: [
